const now = new Date().getTime();
const duasHours = 2 * 60 * 60 * 1000;

const items = $input.all().map(i => i.json).filter(b => {
  if (!b.createdAt) return false;
  const created = new Date(b.createdAt).getTime();
  const diff = now - created;
  // Pendiente entre 2 y 24 horas
  return diff >= duasHours && diff <= 24 * 60 * 60 * 1000 && !b.followUpSent;
});

return items.map(item => ({
  json: {
    bookingId: item.bookingId,
    customerName: item.customerName || 'Viajero',
    customerEmail: item.customerEmail,
    tourName: item.tourName || 'Experiencia Costa Rica Tours',
    totalUSD: item.totalUSD,
    mensaje: `¡Hola ${item.customerName || 'Viajero'}! Notamos que iniciaste tu reserva para ${item.tourName || 'nuestro tour'} pero quedó pendiente de pago. ¿Tienes alguna duda sobre las fechas o métodos de pago (SINPE, Tarjeta, PayPal)? Estamos aquí para ayudarte a asegurar tu espacio. ¡Pura Vida! 🌿`
  }
}));
